using System;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Collections.Generic;
using System.Web.Script.Serialization;
internal sealed class BackupPlan:IDisposable {
 internal string Stage,Parent;internal Data Data;internal int MissingFiles;internal bool Committed;
 public void Dispose(){if(Committed||String.IsNullOrEmpty(Stage)||String.IsNullOrEmpty(Parent))return;string full=Path.GetFullPath(Stage);Guid id;string name=Path.GetFileName(full);if(!String.Equals(Path.GetDirectoryName(full),Path.GetFullPath(Parent),StringComparison.OrdinalIgnoreCase)||!name.StartsWith(".restore-",StringComparison.Ordinal)||!Guid.TryParseExact(name.Substring(9),"N",out id))return;try{if(Directory.Exists(full)&&(File.GetAttributes(full)&FileAttributes.ReparsePoint)==0)Directory.Delete(full,true);}catch(IOException){}catch(UnauthorizedAccessException){}}
}
internal static class FullBackup {
 const long MaxTotal=2L*1024*1024*1024;static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=8*1024*1024};
 static void PlainFile(string path){if((File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException("Un fichier lié ne peut pas être inclus dans la sauvegarde.");}
 static bool AttachmentName(string name){if(String.IsNullOrEmpty(name)||name!=Path.GetFileName(name)||name.IndexOfAny(new[]{'/','\\',':'})>=0)return false;string ext=Path.GetExtension(name);Guid id;return Guid.TryParse(Path.GetFileNameWithoutExtension(name),out id)&&ext.Length<=14&&(ext.Length==0||ext.Skip(1).All(Char.IsLetterOrDigit));}
 static void CopyBounded(Stream source,Stream destination,long limit,ref long total){var buffer=new byte[81920];int read;long count=0;while((read=source.Read(buffer,0,buffer.Length))>0){count+=read;total+=read;if(count>limit||total>MaxTotal)throw new InvalidDataException("Sauvegarde trop volumineuse (2 Go maximum au total).");destination.Write(buffer,0,read);}}
 static void Add(ZipArchive zip,string path,string name,ref long total){PlainFile(path);var entry=zip.CreateEntry(name,CompressionLevel.Optimal);using(var source=File.OpenRead(path))using(var target=entry.Open())CopyBounded(source,target,name=="state.json"?8L*1024*1024:80L*1024*1024,ref total);}
 internal static void Export(Store store,string destination){store.Save();ExportSnapshot(store,destination,Json.Serialize(store.Value));}
 internal static void ExportSnapshot(Store store,string destination,string snapshot){string full=Path.GetFullPath(destination);if(full.StartsWith(Path.GetFullPath(store.Root).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Choisissez un emplacement en dehors du dossier de données de l’application.");string temp=Path.Combine(Path.GetDirectoryName(full),"."+Guid.NewGuid().ToString("N")+".tmp");long total=0;try{using(var output=new FileStream(temp,FileMode.CreateNew,FileAccess.ReadWrite))using(var zip=new ZipArchive(output,ZipArchiveMode.Create)){var state=System.Text.Encoding.UTF8.GetBytes(snapshot);if(state.Length>8*1024*1024)throw new InvalidDataException("Données trop volumineuses.");using(var stateStream=zip.CreateEntry("state.json").Open())stateStream.Write(state,0,state.Length);total+=state.Length;if(File.Exists(store.AudioPath))Add(zip,store.AudioPath,"morning.mp3",ref total);var portraitState=Json.Deserialize<Data>(snapshot);CharacterPortraits.Validate(portraitState);foreach(string hash in portraitState.portraits.Values.Distinct()){string portrait=Path.Combine(store.Root,"Portraits",hash+".png");if(File.Exists(portrait))Add(zip,portrait,"Portraits/"+hash+".png",ref total);}string attachments=Path.Combine(store.Root,"Attachments");if(Directory.Exists(attachments)){if((File.GetAttributes(attachments)&FileAttributes.ReparsePoint)!=0)throw new InvalidDataException("Le dossier de pièces jointes ne doit pas être un lien.");foreach(string path in Directory.GetFiles(attachments)){string name=Path.GetFileName(path);Guid pendingId;if(name.StartsWith(".pending-",StringComparison.Ordinal)&&Guid.TryParseExact(name.Substring(9),"N",out pendingId))continue;if(!AttachmentName(name))throw new InvalidDataException("Nom de pièce jointe invalide : "+name);Add(zip,path,"Attachments/"+name,ref total);}}}if(File.Exists(full))File.Replace(temp,full,null);else File.Move(temp,full);}finally{if(File.Exists(temp))File.Delete(temp);}}
 internal static BackupPlan Prepare(Store store,string source){if(new FileInfo(source).Length>MaxTotal)throw new InvalidDataException("Sauvegarde trop volumineuse.");string root=Path.GetFullPath(store.Root).TrimEnd(Path.DirectorySeparatorChar),parent=Path.GetDirectoryName(root);if(String.IsNullOrEmpty(parent)||root==Path.GetPathRoot(root).TrimEnd(Path.DirectorySeparatorChar))throw new InvalidDataException("Emplacement de restauration invalide.");var plan=new BackupPlan{Parent=parent,Stage=Path.Combine(parent,".restore-"+Guid.NewGuid().ToString("N"))};Directory.CreateDirectory(plan.Stage);try{long total=0;var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);using(var input=File.OpenRead(source))using(var zip=new ZipArchive(input,ZipArchiveMode.Read)){if(zip.Entries.Count>20002)throw new InvalidDataException("Trop de fichiers dans la sauvegarde.");foreach(var entry in zip.Entries){string name=entry.FullName;if(name=="Attachments/"||name=="Portraits/")continue;bool state=name=="state.json",audio=name=="morning.mp3",attachment=name.StartsWith("Attachments/",StringComparison.Ordinal)&&AttachmentName(name.Substring(12));bool portrait=System.Text.RegularExpressions.Regex.IsMatch(name,@"^Portraits/[a-f0-9]{64}\.png$");if((!state&&!audio&&!attachment&&!portrait)||!seen.Add(name))throw new InvalidDataException("Contenu de sauvegarde invalide ou chemin interdit : "+name);long limit=state?8L*1024*1024:portrait?1024L*1024:80L*1024*1024;if(entry.Length>limit||entry.Length<0)throw new InvalidDataException("Un fichier de sauvegarde est trop volumineux.");string target=Path.GetFullPath(Path.Combine(plan.Stage,name.Replace('/',Path.DirectorySeparatorChar)));if(!target.StartsWith(plan.Stage+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Chemin interdit dans la sauvegarde.");Directory.CreateDirectory(Path.GetDirectoryName(target));using(var sourceStream=entry.Open())using(var output=new FileStream(target,FileMode.CreateNew,FileAccess.Write))CopyBounded(sourceStream,output,limit,ref total);if(portrait&&WorkspaceNext.Hash(File.ReadAllBytes(target))!=Path.GetFileNameWithoutExtension(target))throw new InvalidDataException("Portrait de sauvegarde altéré.");}}string json=Path.Combine(plan.Stage,"state.json");if(!File.Exists(json))throw new InvalidDataException("Le fichier state.json manque dans la sauvegarde.");plan.Data=Json.Deserialize<Data>(File.ReadAllText(json));Store.Validate(plan.Data);try{System.Drawing.ColorTranslator.FromHtml(plan.Data.settings.Accent);new System.Windows.Media.BrushConverter().ConvertFromString(plan.Data.settings.Accent);}catch(Exception){throw new InvalidDataException("La couleur des réglages est invalide.");}File.WriteAllText(json,Json.Serialize(plan.Data),new System.Text.UTF8Encoding(false));plan.MissingFiles=plan.Data.projectData.SelectMany(p=>p.files).Count(f=>!File.Exists(Path.Combine(plan.Stage,"Attachments",f.id+f.extension)))+plan.Data.portraits.Values.Count(h=>!File.Exists(Path.Combine(plan.Stage,"Portraits",h+".png")));return plan;}catch{plan.Dispose();throw;}}
 internal static string Commit(Store store,BackupPlan plan){if(plan.Committed||plan.Data==null)throw new InvalidOperationException("Cette restauration n’est pas disponible.");string root=Path.GetFullPath(store.Root).TrimEnd(Path.DirectorySeparatorChar),parent=Path.GetDirectoryName(root);if(Path.GetDirectoryName(Path.GetFullPath(plan.Stage))!=parent||!Path.GetFileName(plan.Stage).StartsWith(".restore-",StringComparison.Ordinal))throw new InvalidDataException("Dossier de restauration invalide.");string previous=Path.Combine(parent,"Data-avant-restauration-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,8));store.Save();Directory.Move(root,previous);try{Directory.Move(plan.Stage,root);}catch{Directory.Move(previous,root);throw;}store.Value=plan.Data;store.ResetNoteBaseline();plan.Committed=true;return previous;}
 internal static void Test(string folder){string home=Path.Combine(folder,"full-backup");var source=new Store(Path.Combine(home,"source"));source.Value.settings.DisplayName="Test complet";source.Value.settings.CloseToTray=false;source.Value.settings.LocalShortcuts.Add(new ModeAction{kind="folder",label="Dossier du PC",target=Path.GetFullPath(home)});source.Value.googlePins.Add(GoogleFiles.FromLink("Sheets sauvegardé","https://docs.google.com/spreadsheets/d/backup_google/edit"));source.Value.settings.Appearance=new AppearanceTheme{mode="gradient",third=true,color2="#263B43",accent="#83CBB7"};source.Value.settings.SavedThemes.Add(Appearance.Clone(source.Value.settings.Appearance));source.Value.modes.Add(new LaunchMode{id="backup-mode",name="Mode sauvegardé",actions=new List<ModeAction>{new ModeAction{kind="discord",label="Discord"}}});source.Value.tasks.Add(new WorkTask{id="deleted-for-backup",title="Supprimée",project="Personnel",status="todo",priority="Normale"});DeletionHistory.Remove(source.Value,"task","deleted-for-backup");source.Value.pages.Add(new NotePage{id="page",title="Note conservée",body="Contenu"});var project=ProjectData.Get(source.Value,"Test");string file=Path.Combine(home,"sample.txt");File.WriteAllText(file,"pièce jointe complète");var attachment=ProjectData.Attach(source,file);project.files.Add(attachment);File.WriteAllText(source.AudioPath,"audio-test");source.Save();string archive=Path.Combine(home,"complete.mespace");Export(source,archive);var target=new Store(Path.Combine(home,"target"));target.Value.pages.Add(new NotePage{id="old",title="Ancienne note",body="ancien"});target.Save();using(var plan=Prepare(target,archive)){if(plan.MissingFiles!=0)throw new Exception("Pièce jointe perdue");string previous=Commit(target,plan);if(!new Store(previous).Value.pages.Any(n=>n.id=="old"))throw new Exception("Sauvegarde avant restauration perdue");}target=new Store(target.Root);if(target.Value.settings.DisplayName!="Test complet"||target.Value.settings.CloseToTray||target.Value.settings.LocalShortcuts.Count!=1||target.Value.googlePins.Count!=1||target.Value.deleted.Count!=1||target.Value.settings.Appearance.mode!="gradient"||!target.Value.settings.Appearance.third||target.Value.settings.SavedThemes.Count!=1||target.Value.modes.Count!=1||target.Value.modes[0].name!="Mode sauvegardé"||target.Value.pages[0].body!="Contenu"||File.ReadAllText(ProjectData.PathFor(target,attachment))!="pièce jointe complète"||File.ReadAllText(target.AudioPath)!="audio-test")throw new Exception("Restauration complète incorrecte");string cancelledStage;using(var cancelled=Prepare(target,archive)){cancelledStage=cancelled.Stage;}if(Directory.Exists(cancelledStage))throw new Exception("Restauration annulée non nettoyée");using(var blocked=Prepare(target,archive)){string held=blocked.Stage+"-held";Directory.Move(blocked.Stage,held);bool rolledBack=false;try{Commit(target,blocked);}catch(DirectoryNotFoundException){rolledBack=true;}catch(IOException){rolledBack=true;}if(!rolledBack||!new Store(target.Root).Value.pages.Any(n=>n.id=="page"))throw new Exception("Retour arrière de restauration invalide");}string malicious=Path.Combine(home,"bad.mespace");using(var output=File.Create(malicious))using(var zip=new ZipArchive(output,ZipArchiveMode.Create)){using(var writer=new StreamWriter(zip.CreateEntry("../escape.txt").Open()))writer.Write("bad");}bool rejected=false;try{Prepare(target,malicious);}catch(InvalidDataException){rejected=true;}if(!rejected||!target.Value.pages.Any(n=>n.id=="page"))throw new Exception("Archive malformée acceptée ou données altérées");string invalid=Path.Combine(home,"invalid.mespace");using(var output=File.Create(invalid))using(var zip=new ZipArchive(output,ZipArchiveMode.Create)){using(var writer=new StreamWriter(zip.CreateEntry("state.json").Open()))writer.Write("{}");using(var writer=new StreamWriter(zip.CreateEntry("STATE.JSON").Open()))writer.Write("{}");}rejected=false;try{Prepare(target,invalid);}catch(InvalidDataException){rejected=true;}if(!rejected)throw new Exception("Doublon archive accepté");}
}
